import os
import requests

def paginate():
    cursor = ""
    while True:
        resp = requests.get(
            "https://api.twitterapis.com/twitter/tweet/advanced_search",
            headers={"Authorization": f"Bearer {os.environ['TWITTERAPIS_KEY']}"},
            params={"query": "from:naval", "cursor": cursor},
        )
        resp.raise_for_status()
        data = resp.json()
        items = data.get("tweets", [])
        if not items:
            break
        for item in items:
            yield item
        cursor = data.get("next_cursor")
        if not cursor:
            break

